def apply_cleaner(df, p):
    # Codes 96/98 default at 54.6% vs 6.6% elsewhere -> keep as a flag, not a delete
    df["late_code_flag"] = (df[LATE_COLS] >= 96).any(axis=1).astype(int)
    for c in LATE_COLS:
        df.loc[df[c] >= 96, c] = p["late_median"][c]
    return df

export async function GET(req: NextRequest, context: { params: { ticketID: string } }) {
  // `params` is a Promise in Next.js 15+, so await it before use
  const { ticketID } = await context.params;

  try {
    await connectDB();
    const trackingData = await Tracking.findOne({ ticketID });

    if (!trackingData) {
      return NextResponse.json({ error: 'Tracking data not found' }, { status: 404 });
    }
    return NextResponse.json(trackingData);
  } catch (error) {
    return NextResponse.json({ error: 'Failed to fetch tracking data' }, { status: 500 });
  }
}

-- Row Level Security: a teacher can only ever reach their own students
alter table public.students enable row level security;
alter table public.records  enable row level security;

create policy "Guru dapat lihat siswa sendiri"
  on public.students for select
  using (teacher_id = auth.uid());

-- Grades inherit the same boundary through the student they belong to
create policy "Guru dapat lihat nilai siswa sendiri"
  on public.records for select
  using (
    student_id in (
      select id from public.students where teacher_id = auth.uid()
    )
  );
